def greedy_outputs(params: Greedy, execution: Execution) -> GreedyOutputs:
    """Build the GreedyOutputs object for this tool."""
    output_file_v: OutputPathType | None = None
    root_v: OutputPathType = execution.output_file(".")
    __v0 = params.get("output")
    if __v0 is not None:
        output_file_v = execution.output_file((__v0 if __v0 is not None else ""))
    return GreedyOutputs(
        root=root_v,
        output_file=output_file_v,
    )

def greedy_execute(params: Greedy, runner: Runner | None = None) -> GreedyOutputs:
    """
    greedy

    Paul's greedy diffeomorphic registration implementation

    Author: Greedy Developers

    URL: https://sites.google.com/view/greedyreg/about

    Args:
        params: The parameters.
        runner: Command runner (defaults to global runner).

    Returns:
        Tool outputs (paths to files produced by the tool).
    """
    greedy_validate(params)
    runner = runner if runner is not None else get_global_runner()
    execution = runner.start_execution(GREEDY_METADATA)
    execution.params(params)
    args = greedy_cargs(params, execution)
    out = greedy_outputs(params, execution)
    execution.run(args)
    return out

